def add_arrays(arr1, arr2):
    result = []
    for a, b in zip(arr1, arr2):
        result.append(a+b)
    return result

def dot_product(arr1, arr2):
    total = 0
    for a, b in zip(arr1, arr2):
        total += a * b
    return total

def merge_sorted(arr1, arr2):
    result = []
    i = j = 0
    while i < len(arr1) and j < len(arr2):
        if arr1[i] < arr2[j]:
            result.append(arr1[i])
            i += 1
        else:
            result.append(arr2[j])
            j += 1
    result.extend(arr1[i:])
    result.extend(arr2[j:])
    return result

def dfs(graph, start, visited=None):
    if visited is None:
        visited = set()
    visited.add(start)
    for neighbor in graph[start]:
        if neighbor not in visited:
            dfs(graph, neighbor, visited)
    return visited

def bfs(graph, start):
    visited = set()
    queue = [start]
    while queue:
        vertex = queue.pop(0)
        if vertex not in visited:
            visited.add(vertex)
            queue.extend(set(graph[vertex]) - visited)
    return visited

def floyd_warshall(matrix):
    n = len(matrix)
    for k in range(n):
        for i in range(n):
            for j in range(n):
                matrix[i][j] = min(matrix[i][j], matrix[i][k] + matrix[k][j])
    return matrix

def recursive_binary_search(arr, target, low=0, high=None):
    if high is None:
        high = len(arr) - 1
    if low > high:
        return -1
    mid = (low + high) // 2
    if arr[mid] == target:
        return mid
    elif arr[mid] < target:
        return recursive_binary_search(arr, target, mid+1, high)
    else:
        return recursive_binary_search(arr, target, low, mid-1)

def iterative_binary_search(arr, target):
    low, high = 0, len(arr)-1
    while low <= high:
        mid = (low+high)//2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid+1
        else:
            high = mid-1
    return -1

def n_queens(n):
    solutions = []
    def solve(queens, xy_diff, xy_sum):
        p = len(queens)
        if p == n:
            solutions.append(queens)
            return
        for q in range(n):
            if q not in queens and p-q not in xy_diff and p+q not in xy_sum:
                solve(queens+[q], xy_diff+[p-q], xy_sum+[p+q])
    solve([], [], [])
    return solutions

def tower_of_hanoi(n, source, target, auxiliary):
    if n == 1:
        return
    tower_of_hanoi(n-1, source, auxiliary, target)
    tower_of_hanoi(n-1, auxiliary, target, source)

def quicksort_worst(arr):
    if len(arr) <= 1:
        return arr
    pivot = arr[0]
    left = [x for x in arr[1:] if x < pivot]
    right = [x for x in arr[1:] if x >= pivot]
    return quicksort_worst(left) + [pivot] + quicksort_worst(right)

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def recursive_determinant(matrix):
    # This is a recursive implementation for determinant (inefficient for large matrices)
    n = len(matrix)
    if n == 1:
        return matrix[0][0]
    det = 0
    for c in range(n):
        minor = [row[:c] + row[c+1:] for row in matrix[1:]]
        det += ((-1)**c) * matrix[0][c] * recursive_determinant(minor)
    return det

def floyd_cycle_detection(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow == fast:
            return True
    return False

def lcs(X, Y):
    m, n = len(X), len(Y)
    L = [[0]*(n+1) for _ in range(m+1)]
    for i in range(m+1):
        for j in range(n+1):
            if i == 0 or j == 0:
                L[i][j] = 0
            elif X[i-1] == Y[j-1]:
                L[i][j] = L[i-1][j-1] + 1
            else:
                L[i][j] = max(L[i-1][j], L[i][j-1])
    return L[m][n]

def edit_distance(X, Y):
    m, n = len(X), len(Y)
    dp = [[0]*(n+1) for _ in range(m+1)]
    for i in range(m+1):
        for j in range(n+1):
            if i == 0:
                dp[i][j] = j
            elif j == 0:
                dp[i][j] = i
            elif X[i-1] == Y[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])
    return dp[m][n]

def subset_sum(arr, target, index=0):
    if target == 0:
        return True
    if index >= len(arr) or target < 0:
        return False
    return subset_sum(arr, target - arr[index], index+1) or subset_sum(arr, target, index+1)

def knapsack_recursive(weights, values, W, n):
    if n == 0 or W == 0:
        return 0
    if weights[n-1] > W:
        return knapsack_recursive(weights, values, W, n-1)
    else:
        return max(knapsack_recursive(weights, values, W, n-1),
                   values[n-1] + knapsack_recursive(weights, values, W-weights[n-1], n-1))

def factorial_recursive(n):
    if n == 0:
        return 1
    return n * factorial_recursive(n-1)

def factorial_iterative(n):
    result = 1
    for i in range(1, n+1):
        result *= i
    return result

def exponentiation_by_squaring(x, n):
    if n == 0:
        return 1
    elif n % 2 == 0:
        return exponentiation_by_squaring(x*x, n//2)
    else:
        return x * exponentiation_by_squaring(x*x, (n-1)//2)

def recursive_sum(n):
    if n == 0:
        return 0
    return n + recursive_sum(n-1)

def sum_of_digits(n):
    if n == 0:
        return 0
    return n % 10 + sum_of_digits(n // 10)

def flatten_list(nested_list):
    flat = []
    for item in nested_list:
        if isinstance(item, list):
            flat.extend(flatten_list(item))
        else:
            flat.append(item)
    return flat

def fib_iterative(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a+b
    return a

def fib_memo(n, memo={}):
    if n in memo:
        return memo[n]
    if n <= 1:
        return n
    memo[n] = fib_memo(n-1, memo) + fib_memo(n-2, memo)
    return memo[n]

def tree_depth(root):
    if not root:
        return 0
    return 1 + max(tree_depth(root.left), tree_depth(root.right))

def inorder_traversal(root):
    if root is None:
        return []
    return inorder_traversal(root.left) + [root.val] + inorder_traversal(root.right)

def preorder_traversal(root):
    if root is None:
        return []
    return [root.val] + preorder_traversal(root.left) + preorder_traversal(root.right)

def postorder_traversal(root):
    if root is None:
        return []
    return postorder_traversal(root.left) + postorder_traversal(root.right) + [root.val]

def level_order_traversal(root):
    from collections import deque
    if not root:
        return []
    result = []
    queue = deque([root])
    while queue:
        node = queue.popleft()
        result.append(node.val)
        if node.left:
            queue.append(node.left)
        if node.right:
            queue.append(node.right)
    return result

def heapify(arr, n, i):
    largest = i
    l = 2*i + 1
    r = 2*i + 2
    if l < n and arr[l] > arr[largest]:
        largest = l
    if r < n and arr[r] > arr[largest]:
        largest = r
    if largest != i:
        arr[i], arr[largest] = arr[largest], arr[i]
        heapify(arr, n, largest)

def build_heap(arr):
    n = len(arr)
    for i in range(n//2 - 1, -1, -1):
        heapify(arr, n, i)
    return arr

def find_median(arr):
    arr.sort()
    mid = len(arr) // 2
    if len(arr) % 2 == 0:
        return (arr[mid-1] + arr[mid]) / 2
    else:
        return arr[mid]

def tree_insert_bst(root, key):
    if root is None:
        return TreeNode(key)
    if key < root.val:
        root.left = tree_insert_bst(root.left, key)
    else:
        root.right = tree_insert_bst(root.right, key)
    return root

def avl_insert(root, key):
    # Simplified version; actual implementation includes rotations.
    if root is None:
        return TreeNode(key)
    if key < root.val:
        root.left = avl_insert(root.left, key)
    else:
        root.right = avl_insert(root.right, key)
    return root

def rb_tree_insert(root, key):
    # Simplified; red-black trees require balancing.
    if root is None:
        return TreeNode(key)
    if key < root.val:
        root.left = rb_tree_insert(root.left, key)
    else:
        root.right = rb_tree_insert(root.right, key)
    return root

def btree_search(root, key):
    i = 0
    while i < len(root.keys) and key > root.keys[i]:
        i += 1
    if i < len(root.keys) and key == root.keys[i]:
        return root
    if root.leaf:
        return None
    return btree_search(root.children[i], key)

def btree_insert(root, key):
    # Simplified insertion in a B-tree.
    if root is None:
        return BTreeNode([key])
    # Insertion logic would involve finding the correct child and splitting if necessary.
    return root

def merge_two_sorted_lists(l1, l2):
    dummy = ListNode(0)
    current = dummy
    while l1 and l2:
        if l1.val < l2.val:
            current.next = l1
            l1 = l1.next
        else:
            current.next = l2
            l2 = l2.next
        current = current.next
    current.next = l1 or l2
    return dummy.next

def detect_cycle(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow == fast:
            return True
    return False

def find_middle(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
    return slow

def kth_from_end(head, k):
    fast = slow = head
    for _ in range(k):
        fast = fast.next
    while fast:
        fast = fast.next
        slow = slow.next
    return slow

def quickselect(arr, k):
    if len(arr) == 1:
        return arr[0]
    pivot = arr[len(arr) // 2]
    lows = [el for el in arr if el < pivot]
    highs = [el for el in arr if el > pivot]
    pivots = [el for el in arr if el == pivot]
    if k < len(lows):
        return quickselect(lows, k)
    elif k < len(lows) + len(pivots):
        return pivots[0]
    else:
        return quickselect(highs, k - len(lows) - len(pivots))

def backtracking_subsets(arr):
    result = []
    def backtrack(start, curr):
        result.append(list(curr))
        for i in range(start, len(arr)):
            curr.append(arr[i])
            backtrack(i+1, curr)
            curr.pop()
    backtrack(0, [])
    return result

def backtracking_combinations(arr, k):
    result = []
    def backtrack(start, curr):
        if len(curr) == k:
            result.append(list(curr))
            return
        for i in range(start, len(arr)):
            curr.append(arr[i])
            backtrack(i+1, curr)
            curr.pop()
    backtrack(0, [])
    return result

def coin_change(coins, amount):
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        for x in range(coin, amount+1):
            dp[x] = min(dp[x], dp[x-coin] + 1)
    return dp[amount] if dp[amount] != float('inf') else -1

def longest_increasing_subsequence(arr):
    n = len(arr)
    lis = [1] * n
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1
    return max(lis)

def longest_common_substring(s1, s2):
    m, n = len(s1), len(s2)
    dp = [[0]*(n+1) for _ in range(m+1)]
    result = 0
    for i in range(1, m+1):
        for j in range(1, n+1):
            if s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
                result = max(result, dp[i][j])
            else:
                dp[i][j] = 0
    return result

def matrix_chain_order(p):
    n = len(p) - 1
    m = [[0]*n for _ in range(n)]
    for l in range(2, n+1):
        for i in range(n - l + 1):
            j = i + l - 1
            m[i][j] = float('inf')
            for k in range(i, j):
                q = m[i][k] + m[k+1][j] + p[i]*p[k+1]*p[j+1]
                m[i][j] = min(m[i][j], q)
    return m[0][n-1]

def optimal_bst(keys, freq):
    n = len(keys)
    cost = [[0]*n for _ in range(n)]
    for i in range(n):
        cost[i][i] = freq[i]
    for L in range(2, n+1):
        for i in range(n-L+1):
            j = i + L - 1
            cost[i][j] = float('inf')
            for r in range(i, j+1):
                c = (cost[i][r-1] if r > i else 0) + (cost[r+1][j] if r < j else 0) + sum(freq[i:j+1])
                cost[i][j] = min(cost[i][j], c)
    return cost[0][n-1]

def find_peak(arr):
    low, high = 0, len(arr)-1
    while low < high:
        mid = (low+high)//2
        if arr[mid] < arr[mid+1]:
            low = mid + 1
        else:
            high = mid
    return arr[low]

def merge_intervals(intervals):
    intervals.sort(key=lambda x: x[0])
    merged = []
    for interval in intervals:
        if not merged or merged[-1][1] < interval[0]:
            merged.append(interval)
        else:
            merged[-1][1] = max(merged[-1][1], interval[1])
    return merged

def sliding_window_max(nums, k):
    from collections import deque
    dq = deque()
    result = []
    for i, num in enumerate(nums):
        while dq and nums[dq[-1]] < num:
            dq.pop()
        dq.append(i)
        if dq[0] == i - k:
            dq.popleft()
        if i >= k - 1:
            result.append(nums[dq[0]])
    return result

def longest_unique_substring(s):
    char_index = {}
    left = 0
    max_length = 0
    for right, char in enumerate(s):
        if char in char_index and char_index[char] >= left:
            left = char_index[char] + 1
        char_index[char] = right
        max_length = max(max_length, right - left + 1)
    return max_length

def climb_stairs(n):
    if n <= 1:
        return 1
    dp = [0]*(n+1)
    dp[0], dp[1] = 1, 1
    for i in range(2, n+1):
        dp[i] = dp[i-1] + dp[i-2]
    return dp[n]

def word_ladder(beginWord, endWord, wordList):
    from collections import deque
    wordSet = set(wordList)
    queue = deque([(beginWord, 1)])
    while queue:
        word, steps = queue.popleft()
        if word == endWord:
            return steps
        for i in range(len(word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                nextWord = word[:i] + c + word[i+1:]
                if nextWord in wordSet:
                    wordSet.remove(nextWord)
                    queue.append((nextWord, steps+1))
    return 0

def word_frequency(text):
    words = text.split()
    freq = {}
    for word in words:
        freq[word] = freq.get(word, 0) + 1
    return freq

def inorder_iterative(root):
    stack, result = [], []
    current = root
    while stack or current:
        if current:
            stack.append(current)
            current = current.left
        else:
            current = stack.pop()
            result.append(current.val)
            current = current.right
    return result

def preorder_iterative(root):
    if not root:
        return []
    stack, result = [root], []
    while stack:
        node = stack.pop()
        result.append(node.val)
        if node.right:
            stack.append(node.right)
        if node.left:
            stack.append(node.left)
    return result

def postorder_iterative(root):
    if not root:
        return []
    stack, result = [root], []
    while stack:
        node = stack.pop()
        result.append(node.val)
        if node.left:
            stack.append(node.left)
        if node.right:
            stack.append(node.right)
    return result[::-1]

def count_nodes(root):
    if not root:
        return 0
    return 1 + count_nodes(root.left) + count_nodes(root.right)

def all_substrings(s):
    substrings = []
    for i in range(len(s)):
        for j in range(i+1, len(s)+1):
            substrings.append(s[i:j])
    return substrings

def power_set(nums):
    if not nums:
        return [[]]
    rest = power_set(nums[1:])
    return rest + [[nums[0]] + subset for subset in rest]

def gray_code(n):
    if n == 0:
        return [0]
    result = gray_code(n-1)
    add = 1 << (n-1)
    return result + [x + add for x in reversed(result)]

def iterative_permutations(arr):
    result = [[]]
    for num in arr:
        new_result = []
        for perm in result:
            for i in range(len(perm)+1):
                new_result.append(perm[:i] + [num] + perm[i:])
        result = new_result
    return result

def spiral_order(matrix):
    result = []
    while matrix:
        result += matrix.pop(0)
        matrix = list(zip(*matrix))[::-1]
    return result

def zigzag_level_order(root):
    if not root:
        return []
    results, level, direction = [], [root], 1
    while level:
        current_vals = [node.val for node in level]
        results.append(current_vals if direction > 0 else current_vals[::-1])
        next_level = []
        for node in level:
            if node.left: next_level.append(node.left)
            if node.right: next_level.append(node.right)
        level = next_level
        direction *= -1
    return results

def sum_recursive(arr, idx=0):
    if idx == len(arr):
        return 0
    return arr[idx] + sum_recursive(arr, idx+1)

def z_algorithm(s):
    n = len(s)
    z = [0] * n
    l, r = 0, 0
    for i in range(1, n):
        if i > r:
            l, r = i, i
            while r < n and s[r-l] == s[r]:
                r += 1
            z[i] = r - l
            r -= 1
        else:
            k = i - l
            if z[k] < r - i + 1:
                z[i] = z[k]
            else:
                l = i
                while r < n and s[r-l] == s[r]:
                    r += 1
                z[i] = r - l
                r -= 1
    return z

def boyer_moore(text, pattern):
    def bad_character_table(pattern):
        table = {}
        for i, char in enumerate(pattern):
            table[char] = i
        return table
    table = bad_character_table(pattern)
    m, n = len(pattern), len(text)
    i = m - 1
    while i < n:
        j = m - 1
        k = i
        while j >= 0 and text[k] == pattern[j]:
            j -= 1
            k -= 1
        if j < 0:
            return k + 1
        shift = m - min(j, table.get(text[i], -1) + 1)
        i += shift
    return -1

def balanced_parentheses(s):
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}
    for char in s:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping:
            if not stack or mapping[char] != stack.pop():
                return False
    return not stack

def evaluate_postfix(expression):
    stack = []
    for token in expression.split():
        if token.isdigit():
            stack.append(int(token))
        else:
            b, a = stack.pop(), stack.pop()
            if token == '+': stack.append(a + b)
            elif token == '-': stack.append(a - b)
            elif token == '*': stack.append(a * b)
            elif token == '/': stack.append(a / b)
    return stack[0]

def evaluate_prefix(expression):
    tokens = expression.split()[::-1]
    stack = []
    for token in tokens:
        if token.isdigit():
            stack.append(int(token))
        else:
            a, b = stack.pop(), stack.pop()
            if token == '+': stack.append(a + b)
            elif token == '-': stack.append(a - b)
            elif token == '*': stack.append(a * b)
            elif token == '/': stack.append(a / b)
    return stack[0]

def infix_to_postfix(expression):
    precedence = {'+':1, '-':1, '*':2, '/':2}
    output = []
    stack = []
    for token in expression.split():
        if token.isalnum():
            output.append(token)
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            stack.pop()
        else:
            while stack and stack[-1] != '(' and precedence.get(token,0) <= precedence.get(stack[-1],0):
                output.append(stack.pop())
            stack.append(token)
    while stack:
        output.append(stack.pop())
    return ' '.join(output)

def longest_palindrome_dp(s):
    n = len(s)
    dp = [[False]*n for _ in range(n)]
    start, max_len = 0, 1
    for i in range(n):
        dp[i][i] = True
    for i in range(n-1):
        if s[i] == s[i+1]:
            dp[i][i+1] = True
            start, max_len = i, 2
    for length in range(3, n+1):
        for i in range(n-length+1):
            j = i + length - 1
            if s[i] == s[j] and dp[i+1][j-1]:
                dp[i][j] = True
                start, max_len = i, length
    return s[start:start+max_len]

def manacher(s):
    A = '@#' + '#'.join(s) + '#$'
    Z = [0] * len(A)
    center = right = 0
    for i in range(1, len(A)-1):
        if i < right:
            Z[i] = min(right - i, Z[2*center - i])
        while A[i + Z[i] + 1] == A[i - Z[i] - 1]:
            Z[i] += 1
        if i + Z[i] > right:
            center, right = i, i + Z[i]
    return max(Z)

def count_binary_substrings(s):
    count, prev, curr = 0, 0, 1
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            curr += 1
        else:
            count += min(prev, curr)
            prev, curr = curr, 1
    count += min(prev, curr)
    return count

def max_subarray_sum(arr):
    max_current = max_global = arr[0]
    for x in arr[1:]:
        max_current = max(x, max_current + x)
        max_global = max(max_global, max_current)
    return max_global

def merge_two_sorted_linked_lists(l1, l2):
    if not l1:
        return l2
    if not l2:
        return l1
    if l1.val < l2.val:
        l1.next = merge_two_sorted_linked_lists(l1.next, l2)
        return l1
    else:
        l2.next = merge_two_sorted_linked_lists(l1, l2.next)
        return l2

def reverse_string_recursive(s):
    if len(s) <= 1:
        return s
    return reverse_string_recursive(s[1:]) + s[0]

def remove_duplicates_sorted(arr):
    if not arr:
        return 0
    j = 0
    for i in range(1, len(arr)):
        if arr[i] != arr[j]:
            j += 1
            arr[j] = arr[i]
    return j + 1

def rotate_array(arr, k):
    k %= len(arr)
    return arr[-k:] + arr[:-k]

def pivot_index(arr):
    total = sum(arr)
    left_sum = 0
    for i, x in enumerate(arr):
        if left_sum == total - left_sum - x:
            return i
        left_sum += x
    return -1

def spiral_matrix(n):
    matrix = [[0]*n for _ in range(n)]
    num = 1
    for layer in range((n+1)//2):
        for i in range(layer, n-layer):
            matrix[layer][i] = num
            num += 1
        for i in range(layer+1, n-layer):
            matrix[i][n-layer-1] = num
            num += 1
        for i in range(n-layer-2, layer-1, -1):
            matrix[n-layer-1][i] = num
            num += 1
        for i in range(n-layer-2, layer, -1):
            matrix[i][layer] = num
            num += 1
    return matrix

def generate_pascals_triangle(n):
    triangle = []
    for i in range(n):
        row = [1]*(i+1)
        for j in range(1, i):
            row[j] = triangle[i-1][j-1] + triangle[i-1][j]
        triangle.append(row)
    return triangle

def jump_game(nums):
    max_reach = 0
    for i, x in enumerate(nums):
        if i > max_reach:
            return False
        max_reach = max(max_reach, i+x)
    return True

def majority_element(nums):
    count, candidate = 0, None
    for num in nums:
        if count == 0:
            candidate = num
        count += (1 if num == candidate else -1)
    return candidate

def find_duplicate(nums):
    slow = fast = nums[0]
    while True:
        slow = nums[slow]
        fast = nums[nums[fast]]
        if slow == fast:
            break
    slow = nums[0]
    while slow != fast:
        slow = nums[slow]
        fast = nums[fast]
    return slow

def subarray_sum_equals_k(nums, k):
    count = 0
    cumulative_sum = 0
    sums = {0: 1}
    for num in nums:
        cumulative_sum += num
        if cumulative_sum - k in sums:
            count += sums[cumulative_sum - k]
        sums[cumulative_sum] = sums.get(cumulative_sum, 0) + 1
    return count

def number_of_islands(grid):
    if not grid: return 0
    count = 0
    rows, cols = len(grid), len(grid[0])
    def dfs(r, c):
        if r < 0 or c < 0 or r >= rows or c >= cols or grid[r][c] != '1':
            return
        grid[r][c] = '0'
        dfs(r+1, c)
        dfs(r-1, c)
        dfs(r, c+1)
        dfs(r, c-1)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '1':
                dfs(r, c)
                count += 1
    return count

def pascal_triangle_row(n):
    row = [1]
    for k in range(1, n+1):
        row.append(row[-1] * (n - k + 1) // k)
    return row

def merge_sort_iterative(arr):
    width = 1
    n = len(arr)
    while width < n:
        for i in range(0, n, 2*width):
            left = arr[i:i+width]
            right = arr[i+width:i+2*width]
            arr[i:i+2*width] = merge_sorted(left, right)
        width *= 2
    return arr

def word_count(text):
    counts = {}
    for word in text.split():
        counts[word] = counts.get(word, 0) + 1
    return counts

def inorder_morris(root):
    result = []
    current = root
    while current:
        if not current.left:
            result.append(current.val)
            current = current.right
        else:
            pre = current.left
            while pre.right and pre.right != current:
                pre = pre.right
            if not pre.right:
                pre.right = current
                current = current.left
            else:
                pre.right = None
                result.append(current.val)
                current = current.right
    return result

def preorder_morris(root):
    result = []
    current = root
    while current:
        if not current.left:
            result.append(current.val)
            current = current.right
        else:
            pre = current.left
            while pre.right and pre.right != current:
                pre = pre.right
            if not pre.right:
                result.append(current.val)
                pre.right = current
                current = current.left
            else:
                pre.right = None
                current = current.right
    return result

def morris_postorder_traversal(root):
    result = []
    dummy = TreeNode(0)
    dummy.left = root
    current = dummy
    while current:
        if not current.left:
            current = current.right
        else:
            pre = current.left
            while pre.right and pre.right != current:
                pre = pre.right
            if not pre.right:
                pre.right = current
                current = current.left
            else:
                temp = []
                node = current.left
                while node != pre.right:
                    temp.append(node.val)
                    node = node.right
                result.extend(temp[::-1])
                pre.right = None
                current = current.right
    return result

def two_sum_sorted(arr, target):
    left, right = 0, len(arr)-1
    while left < right:
        s = arr[left] + arr[right]
        if s == target:
            return (left, right)
        elif s < target:
            left += 1
        else:
            right -= 1
    return (-1, -1)

def three_sum_sorted(arr):
    arr.sort()
    result = []
    n = len(arr)
    for i in range(n-2):
        left, right = i+1, n-1
        while left < right:
            s = arr[i] + arr[left] + arr[right]
            if s == 0:
                result.append((arr[i], arr[left], arr[right]))
                left += 1
                right -= 1
            elif s < 0:
                left += 1
            else:
                right -= 1
    return result

def four_sum(arr, target):
    arr.sort()
    result = []
    n = len(arr)
    for i in range(n-3):
        for j in range(i+1, n-2):
            left, right = j+1, n-1
            while left < right:
                s = arr[i] + arr[j] + arr[left] + arr[right]
                if s == target:
                    result.append((arr[i], arr[j], arr[left], arr[right]))
                    left += 1
                    right -= 1
                elif s < target:
                    left += 1
                else:
                    right -= 1
    return result

def count_subarrays_with_sum(arr, k):
    count = 0
    for i in range(len(arr)):
        s = 0
        for j in range(i, len(arr)):
            s += arr[j]
            if s == k:
                count += 1
    return count

def min_window_substring(s, t):
    from collections import Counter
    dict_t = Counter(t)
    required = len(dict_t)
    l, r = 0, 0
    formed = 0
    window_counts = {}
    ans = float('inf'), None, None
    while r < len(s):
        character = s[r]
        window_counts[character] = window_counts.get(character, 0) + 1
        if character in dict_t and window_counts[character] == dict_t[character]:
            formed += 1
        while l <= r and formed == required:
            character = s[l]
            if r - l + 1 < ans[0]:
                ans = (r - l + 1, l, r)
            window_counts[character] -= 1
            if character in dict_t and window_counts[character] < dict_t[character]:
                formed -= 1
            l += 1
        r += 1
    return '' if ans[0] == float('inf') else s[ans[1]:ans[2]+1]

def find_anagrams(s, p):
    from collections import Counter
    p_count = Counter(p)
    s_count = Counter()
    result = []
    p_length = len(p)
    for i, char in enumerate(s):
        s_count[char] += 1
        if i >= p_length:
            if s_count[s[i-p_length]] == 1:
                del s_count[s[i-p_length]]
            else:
                s_count[s[i-p_length]] -= 1
        if s_count == p_count:
            result.append(i - p_length + 1)
    return result

def evaluate_rpn(tokens):
    stack = []
    for token in tokens:
        if token not in '+-*/':
            stack.append(int(token))
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a+b)
            elif token == '-':
                stack.append(a-b)
            elif token == '*':
                stack.append(a*b)
            else:
                stack.append(int(a/b))
    return stack[0]

def expression_tree_evaluation(root):
    if not root:
        return 0
    if not root.left and not root.right:
        return int(root.val)
    left_val = expression_tree_evaluation(root.left)
    right_val = expression_tree_evaluation(root.right)
    if root.val == '+':
        return left_val + right_val
    elif root.val == '-':
        return left_val - right_val
    elif root.val == '*':
        return left_val * right_val
    else:
        return left_val / right_val

def bst_to_sorted_list(root):
    result = []
    def inorder(node):
        if not node:
            return
        inorder(node.left)
        result.append(node.val)
        inorder(node.right)
    inorder(root)
    return result

def sorted_list_to_bst(nums):
    def helper(l, r):
        if l > r:
            return None
        m = (l + r) // 2
        node = TreeNode(nums[m])
        node.left = helper(l, m-1)
        node.right = helper(m+1, r)
        return node
    return helper(0, len(nums)-1)

def validate_bst(root, low=float('-inf'), high=float('inf')):
    if not root:
        return True
    if not (low < root.val < high):
        return False
    return validate_bst(root.left, low, root.val) and validate_bst(root.right, root.val, high)

def lowest_common_ancestor_bt(root, p, q):
    if not root or root == p or root == q:
        return root
    left = lowest_common_ancestor_bt(root.left, p, q)
    right = lowest_common_ancestor_bt(root.right, p, q)
    if left and right:
        return root
    return left or right

def serialize_tree(root):
    def helper(node):
        if not node:
            vals.append('#')
        else:
            vals.append(str(node.val))
            helper(node.left)
            helper(node.right)
    vals = []
    helper(root)
    return ' '.join(vals)

def deserialize_tree(data):
    def helper(vals):
        if vals[0] == '#':
            vals.pop(0)
            return None
        node = TreeNode(int(vals.pop(0)))
        node.left = helper(vals)
        node.right = helper(vals)
        return node
    vals = data.split()
    return helper(vals)

def find_missing_numbers(nums):
    full_set = set(range(min(nums), max(nums)+1))
    return list(full_set - set(nums))

def two_sum_unsorted(nums, target):
    seen = {}
    for num in nums:
        if target - num in seen:
            return True
        seen[num] = True
    return False

def three_sum_closest(nums, target):
    nums.sort()
    closest = float('inf')
    for i in range(len(nums)-2):
        left, right = i+1, len(nums)-1
        while left < right:
            s = nums[i] + nums[left] + nums[right]
            if abs(s - target) < abs(closest - target):
                closest = s
            if s < target:
                left += 1
            else:
                right -= 1
    return closest

def four_sum(arr, target):
    arr.sort()
    result = []
    n = len(arr)
    for i in range(n-3):
        for j in range(i+1, n-2):
            left, right = j+1, n-1
            while left < right:
                s = arr[i] + arr[j] + arr[left] + arr[right]
                if s == target:
                    result.append((arr[i], arr[j], arr[left], arr[right]))
                    left += 1
                    right -= 1
                elif s < target:
                    left += 1
                else:
                    right -= 1
    return result

def count_subarrays_with_product_less_than_k(nums, k):
    if k <= 1:
        return 0
    prod = 1
    count = left = 0
    for right, val in enumerate(nums):
        prod *= val
        while prod >= k:
            prod //= nums[left]
            left += 1
        count += right - left + 1
    return count

def longest_common_prefix(strs):
    if not strs:
        return ''
    prefix = strs[0]
    for s in strs[1:]:
        while s.find(prefix) != 0:
            prefix = prefix[:-1]
            if not prefix:
                return ''
    return prefix

def find_longest_word(words):
    longest = ''
    for word in words:
        if len(word) > len(longest):
            longest = word
    return longest

def sort_by_frequency(s):
    from collections import Counter
    counts = Counter(s)
    return ''.join(sorted(s, key=lambda x: counts[x]))

def longest_increasing_subsequence_binary_search(nums):
    import bisect
    sub = []
    for num in nums:
        pos = bisect.bisect_left(sub, num)
        if pos == len(sub):
            sub.append(num)
        else:
            sub[pos] = num
    return len(sub)

def merge_intervals_recursive(intervals):
    if not intervals:
        return []
    intervals.sort(key=lambda x: x[0])
    def merge_recursive(lst):
        if len(lst) <= 1:
            return lst
        merged = []
        i = 0
        while i < len(lst):
            current = lst[i]
            while i+1 < len(lst) and lst[i+1][0] <= current[1]:
                current = [current[0], max(current[1], lst[i+1][1])]
                i += 1
            merged.append(current)
            i += 1
        return merged
    return merge_recursive(intervals)

def matrix_addition(A, B):
    n, m = len(A), len(A[0])
    return [[A[i][j] + B[i][j] for j in range(m)] for i in range(n)]

def matrix_subtraction(A, B):
    n, m = len(A), len(A[0])
    return [[A[i][j] - B[i][j] for j in range(m)] for i in range(n)]

def gcd_iterative(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    def gcd(a, b):
        return a if b == 0 else gcd(b, a % b)
    return a * b // gcd(a, b)

def level_order_recursive(root):
    result = []
    def helper(nodes):
        if not nodes:
            return
        next_level = []
        level_vals = []
        for node in nodes:
            level_vals.append(node.val)
            if node.left: next_level.append(node.left)
            if node.right: next_level.append(node.right)
        result.append(level_vals)
        helper(next_level)
    helper([root])
    return result

def count_leaves(root):
    if not root:
        return 0
    if not root.left and not root.right:
        return 1
    return count_leaves(root.left) + count_leaves(root.right)

def bst_search_iterative(root, key):
    while root:
        if root.val == key:
            return True
        root = root.left if key < root.val else root.right
    return False

def bst_search_recursive(root, key):
    if not root:
        return False
    if root.val == key:
        return True
    return bst_search_recursive(root.left, key) if key < root.val else bst_search_recursive(root.right, key)

def tree_height_iterative(root):
    if not root:
        return 0
    height = 0
    queue = [root]
    while queue:
        height += 1
        queue = [child for node in queue for child in (node.left, node.right) if child]
    return height

def tree_height_recursive(root):
    if not root:
        return 0
    return 1 + max(tree_height_recursive(root.left), tree_height_recursive(root.right))

def serialize_preorder(root):
    if not root:
        return '#'
    return str(root.val) + ' ' + serialize_preorder(root.left) + ' ' + serialize_preorder(root.right)

def sum_of_digits_iterative(n):
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

def reverse_digits_iterative(n):
    rev = 0
    while n:
        rev = rev * 10 + n % 10
        n //= 10
    return rev

def reverse_digits_recursive(n, rev=0):
    if n == 0:
        return rev
    return reverse_digits_recursive(n // 10, rev * 10 + n % 10)

def count_trailing_zeros(n):
    count = 0
    while n:
        n //= 5
        count += n
    return count

def count_ones(n):
    count = 0
    while n:
        count += n & 1
        n >>= 1
    return count

def bit_count(n):
    count = 0
    while n:
        n &= n - 1
        count += 1
    return count

def power_iterative(x, n):
    result = 1
    while n:
        if n % 2:
            result *= x
        x *= x
        n //= 2
    return result

def power_recursive(x, n):
    if n == 0:
        return 1
    half = power_recursive(x, n//2)
    return half * half if n % 2 == 0 else x * half * half

def geometric_sum(n, a, r):
    if r == 1:
        return a * n
    return a * (1 - r**n) // (1 - r)

def sieve_sundaram(n):
    k = (n-2)//2
    marked = [False]*(k+1)
    for i in range(1, k+1):
        j = i
        while i + j + 2*i*j <= k:
            marked[i+j+2*i*j] = True
            j += 1
    primes = [2] if n > 2 else []
    for i in range(1, k+1):
        if not marked[i]:
            primes.append(2*i+1)
    return primes

def find_missing_number(arr, n):
    expected = n*(n+1)//2
    return expected - sum(arr)

def find_duplicate_sort(arr):
    arr.sort()
    for i in range(1, len(arr)):
        if arr[i] == arr[i-1]:
            return arr[i]
    return None

def remove_duplicates(lst):
    seen = set()
    result = []
    for item in lst:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def longest_consecutive(nums):
    num_set = set(nums)
    longest = 0
    for num in nums:
        if num - 1 not in num_set:
            length = 1
            while num + length in num_set:
                length += 1
            longest = max(longest, length)
    return longest

def count_islands(grid):
    if not grid: return 0
    rows, cols = len(grid), len(grid[0])
    count = 0
    def dfs(i, j):
        if i < 0 or j < 0 or i >= rows or j >= cols or grid[i][j] != 1:
            return
        grid[i][j] = 0
        dfs(i+1, j); dfs(i-1, j); dfs(i, j+1); dfs(i, j-1)
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                dfs(i, j)
                count += 1
    return count

def maximal_rectangle(matrix):
    if not matrix: return 0
    max_area = 0
    dp = [0]*len(matrix[0])
    for row in matrix:
        for j in range(len(row)):
            dp[j] = dp[j] + 1 if row[j] == '1' else 0
        area = largest_rectangle_area(dp)
        max_area = max(max_area, area)
    return max_area

def maximal_square(matrix):
    if not matrix: return 0
    rows, cols = len(matrix), len(matrix[0])
    dp = [[0]*cols for _ in range(rows)]
    max_side = 0
    for i in range(rows):
        for j in range(cols):
            if matrix[i][j] == '1':
                dp[i][j] = 1 if i==0 or j==0 else 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])
                max_side = max(max_side, dp[i][j])
    return max_side*max_side

def min_cost_stairs(cost):
    n = len(cost)
    dp = [0]*(n+1)
    for i in range(2, n+1):
        dp[i] = min(dp[i-1] + cost[i-1], dp[i-2] + cost[i-2])
    return dp[n]

def house_robber_recursive(nums, i=0, memo={}):
    if i >= len(nums):
        return 0
    if i in memo:
        return memo[i]
    memo[i] = max(nums[i] + house_robber_recursive(nums, i+2, memo),
                  house_robber_recursive(nums, i+1, memo))
    return memo[i]

def fib_fast_doubling(n):
    if n == 0:
        return (0, 1)
    a, b = fib_fast_doubling(n//2)
    c = a*(2*b - a)
    d = a*a + b*b
    return (c, d) if n % 2 == 0 else (d, c+d)

def catalan_dp(n):
    catalan = [0]*(n+1)
    catalan[0] = catalan[1] = 1
    for i in range(2, n+1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i-j-1]
    return catalan[n]

def subset_sum(arr, target, i=0):
    if target == 0:
        return True
    if i >= len(arr) or target < 0:
        return False
    return subset_sum(arr, target - arr[i], i+1) or subset_sum(arr, target, i+1)

def longest_palindromic_subsequence(s):
    n = len(s)
    dp = [[0]*n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1
    for cl in range(2, n+1):
        for i in range(n-cl+1):
            j = i+cl-1
            if s[i] == s[j] and cl == 2:
                dp[i][j] = 2
            elif s[i] == s[j]:
                dp[i][j] = dp[i+1][j-1] + 2
            else:
                dp[i][j] = max(dp[i][j-1], dp[i+1][j])
    return dp[0][n-1]

def longest_repeating_subsequence(s):
    n = len(s)
    dp = [[0]*(n+1) for _ in range(n+1)]
    for i in range(1, n+1):
        for j in range(1, n+1):
            if s[i-1] == s[j-1] and i != j:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])
    return dp[n][n]

def check_parentheses(s):
    stack = []
    mapping = {')':'(', '}':'{', ']':'['}
    for char in s:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping:
            if not stack or stack.pop() != mapping[char]:
                return False
    return not stack

def evaluate_infix(expr):
    import operator
    ops = {'+': operator.add, '-': operator.sub, '*': operator.mul, '/': operator.truediv}
    tokens = expr.split()
    stack = []
    for token in tokens:
        if token in ops:
            b, a = stack.pop(), stack.pop()
            stack.append(ops[token](a, b))
        else:
            stack.append(float(token))
    return stack[0]

def determinant(matrix):
    if len(matrix) == 1:
        return matrix[0][0]
    if len(matrix) == 2:
        return matrix[0][0]*matrix[1][1] - matrix[0][1]*matrix[1][0]
    det = 0
    for c in range(len(matrix)):
        submatrix = [row[:c] + row[c+1:] for row in matrix[1:]]
        det += ((-1)**c) * matrix[0][c] * determinant(submatrix)
    return det

def invert_matrix(matrix):
    n = len(matrix)
    aug = [row + [1 if i==j else 0 for j in range(n)] for i, row in enumerate(matrix)]
    for i in range(n):
        pivot = aug[i][i]
        aug[i] = [x/pivot for x in aug[i]]
        for j in range(n):
            if j != i:
                factor = aug[j][i]
                aug[j] = [x - factor*y for x, y in zip(aug[j], aug[i])]
    return [row[n:] for row in aug]

def gaussian_elimination(A, b):
    n = len(b)
    for i in range(n):
        pivot = A[i][i]
        A[i] = [x/pivot for x in A[i]]
        b[i] /= pivot
        for j in range(n):
            if j != i:
                factor = A[j][i]
                A[j] = [a - factor*x for a, x in zip(A[j], A[i])]
                b[j] -= factor*b[i]
    return b

def matrix_rank(matrix):
    m = [row[:] for row in matrix]
    rows, cols = len(m), len(m[0])
    rank = 0
    for c in range(cols):
        pivot = None
        for r in range(rank, rows):
            if m[r][c] != 0:
                pivot = r
                break
        if pivot is not None:
            m[rank], m[pivot] = m[pivot], m[rank]
            pivot_val = m[rank][c]
            m[rank] = [x / pivot_val for x in m[rank]]
            for r in range(rows):
                if r != rank:
                    factor = m[r][c]
                    m[r] = [x - factor*y for x, y in zip(m[r], m[rank])]
            rank += 1
    return rank

def polynomial_multiply(p, q):
    result = [0]*(len(p)+len(q)-1)
    for i in range(len(p)):
        for j in range(len(q)):
            result[i+j] += p[i]*q[j]
    return result

def horner(poly, x):
    result = 0
    for coeff in poly:
        result = result*x + coeff
    return result

def count_inversions(arr):
    def update(BIT, i, n):
        while i < len(BIT):
            BIT[i] += 1
            i += i & -i
    def query(BIT, i):
        s = 0
        while i:
            s += BIT[i]
            i -= i & -i
        return s
    max_val = max(arr)
    BIT = [0]*(max_val+1)
    inv_count = 0
    for num in reversed(arr):
        inv_count += query(BIT, num-1)
        update(BIT, num, max_val)
    return inv_count

def build_segment_tree(arr):
    n = len(arr)
    seg = [0]*(2*n)
    for i in range(n):
        seg[n+i] = arr[i]
    for i in range(n-1, 0, -1):
        seg[i] = seg[2*i] + seg[2*i+1]
    return seg

def segment_tree_query(seg, n, l, r):
    l += n; r += n
    s = 0
    while l < r:
        if l & 1:
            s += seg[l]
            l += 1
        if r & 1:
            r -= 1
            s += seg[r]
        l //= 2; r //= 2
    return s

def segment_tree_update(seg, n, index, value):
    index += n
    seg[index] = value
    while index > 1:
        index //= 2
        seg[index] = seg[2*index] + seg[2*index+1]

def build_sparse_table(arr):
    import math
    n = len(arr)
    k = int(math.log2(n)) + 1
    st = [[0]*n for _ in range(k)]
    st[0] = arr[:]
    for j in range(1, k):
        for i in range(n - (1 << j) + 1):
            st[j][i] = min(st[j-1][i], st[j-1][i + (1 << (j-1))])
    return st

def query_sparse_table(st, L, R):
    import math
    j = int(math.log2(R-L+1))
    return min(st[j][L], st[j][R - (1 << j) + 1])

def count_leaves_iterative(root):
    if not root:
        return 0
    count = 0
    stack = [root]
    while stack:
        node = stack.pop()
        if not node.left and not node.right:
            count += 1
        if node.left:
            stack.append(node.left)
        if node.right:
            stack.append(node.right)
    return count

def is_balanced(root):
    def height_and_balance(node):
        if not node:
            return (0, True)
        left_height, left_balanced = height_and_balance(node.left)
        right_height, right_balanced = height_and_balance(node.right)
        balanced = left_balanced and right_balanced and abs(left_height - right_height) <= 1
        return (max(left_height, right_height) + 1, balanced)
    return height_and_balance(root)[1]

def detect_cycle_linked_list(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow == fast:
            return True
    return False

def find_middle_linked_list(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
    return slow

def lru_cache_get_item(cache, key):
    from collections import OrderedDict
    if key in cache:
        cache.move_to_end(key)
        return cache[key]
    return -1

def lru_cache_set_item(cache, key, value, capacity):
    from collections import OrderedDict
    if key in cache:
        cache.move_to_end(key)
    cache[key] = value
    if len(cache) > capacity:
        cache.popitem(last=False)

def char_frequency(s):
    freq = {}
    for char in s:
        freq[char] = freq.get(char, 0) + 1
    return freq

def group_by_frequency(lst):
    from collections import defaultdict
    d = defaultdict(list)
    for item in lst:
        d[item].append(item)
    return d

def longest_unique_substring(s):
    char_index = {}
    start = 0
    max_len = 0
    for i, char in enumerate(s):
        if char in char_index and char_index[char] >= start:
            start = char_index[char] + 1
        char_index[char] = i
        max_len = max(max_len, i - start + 1)
    return max_len

def two_sum_hash(nums, target):
    lookup = {}
    for i, num in enumerate(nums):
        if target - num in lookup:
            return (lookup[target - num], i)
        lookup[num] = i
    return None

def three_sum(nums):
    nums.sort()
    result = []
    for i in range(len(nums)-2):
        if i > 0 and nums[i] == nums[i-1]:
            continue
        l, r = i+1, len(nums)-1
        while l < r:
            s = nums[i] + nums[l] + nums[r]
            if s == 0:
                result.append((nums[i], nums[l], nums[r]))
                l += 1; r -= 1
            elif s < 0:
                l += 1
            else:
                r -= 1
    return result

def insertion_sort(arr):
    for i in range(1, len(arr)):
        key = arr[i]
        j = i-1
        while j >= 0 and arr[j] > key:
            arr[j+1] = arr[j]
            j -= 1
        arr[j+1] = key
    return arr

def merge_sort_iterative(arr):
    width = 1
    n = len(arr)
    while width < n:
        for i in range(0, n, 2*width):
            left = arr[i:i+width]
            right = arr[i+width:i+2*width]
            arr[i:i+2*width] = merge_sorted_arrays(left, right)
        width *= 2
    return arr

def linear_search(arr, target):
    for i in range(len(arr)):
        if arr[i] == target:
            return i
    return -1

def sum_elements(arr):
    total = 0
    for elem in arr:
        total += elem
    return total

def binary_search(arr, target):
    low, high = 0, len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n-1)

def calculate_average(numbers):
    total = 0
    for num in numbers:
        total += num
    return total / len(numbers) if numbers else 0

def merge_sort(arr):
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])
    return merge(left, right)

def merge(left, right):
    result = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] < right[j]:
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1
    result.extend(left[i:])
    result.extend(right[j:])
    return result

def find_max(arr):
    if not arr:
        return None
    max_val = arr[0]
    for i in range(1, len(arr)):
        if arr[i] > max_val:
            max_val = arr[i]
    return max_val

def power(x, n):
    if n == 0:
        return 1
    if n % 2 == 0:
        return power(x * x, n // 2)
    else:
        return x * power(x * x, n // 2)

def fibonacci(n):
    if n <= 1:
        return n
    return fibonacci(n-1) + fibonacci(n-2)

def check_duplicates(arr):
    seen = set()
    for item in arr:
        if item in seen:
            return True
        seen.add(item)
    return False

def two_sum(nums, target):
    seen = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            return [seen[complement], i]
        seen[num] = i
    return []

def quicksort(arr):
    if len(arr) <= 1:
        return arr
    pivot = arr[len(arr) // 2]
    left = [x for x in arr if x < pivot]
    middle = [x for x in arr if x == pivot]
    right = [x for x in arr if x > pivot]
    return quicksort(left) + middle + quicksort(right)

def is_sorted(arr):
    for i in range(len(arr) - 1):
        if arr[i] > arr[i + 1]:
            return False
    return True

def intersection(list1, list2):
    set1 = set(list1)
    result = []
    for item in list2:
        if item in set1:
            result.append(item)
    return result

def nth_fibonacci_iterative(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def exponential_complexity(n):
    if n <= 0:
        return 1
    return exponential_complexity(n-1) + exponential_complexity(n-1)

def permutations(arr):
    if len(arr) <= 1:
        return [arr]
    result = []
    for i in range(len(arr)):
        current = arr[i]
        remaining = arr[:i] + arr[i+1:]
        for p in permutations(remaining):
            result.append([current] + p)
    return result

def detect_cycle(head):
    if not head or not head.next:
        return False
    slow = head
    fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow == fast:
            return True
    return False

def tiling_problem(n):
    if n <= 2:
        return n
    dp = [0] * (n + 1)
    dp[1] = 1
    dp[2] = 2
    for i in range(3, n + 1):
        dp[i] = dp[i-1] + dp[i-2]
    return dp[n]

def find_duplicate(nums):
    slow = nums[0]
    fast = nums[0]
    while True:
        slow = nums[slow]
        fast = nums[nums[fast]]
        if slow == fast:
            break

    slow = nums[0]
    while slow != fast:
        slow = nums[slow]
        fast = nums[fast]

    return slow

def kadane_algorithm(nums):
    current_max = global_max = nums[0]

    for i in range(1, len(nums)):
        current_max = max(nums[i], current_max + nums[i])
        global_max = max(global_max, current_max)

    return global_max

def jump_game(nums):
    max_reach = 0
    for i in range(len(nums)):
        if i > max_reach:
            return False
        max_reach = max(max_reach, i + nums[i])
    return True

def valid_parentheses(s):
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in mapping:
            top_element = stack.pop() if stack else '#'
            if mapping[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack

def swap_first_last(arr):
    if len(arr) <= 1:
        return arr
    arr[0], arr[-1] = arr[-1], arr[0]
    return arr

def count_frequency(arr):
    freq = {}
    for item in arr:
        if item in freq:
            freq[item] += 1
        else:
            freq[item] = 1
    return freq

def list_sum_recursive(lst):
    if not lst:
        return 0
    return lst[0] + list_sum_recursive(lst[1:])

def find_second_largest(arr):
    if len(arr) < 2:
        return None

    largest = second = float('-inf')
    for num in arr:
        if num > largest:
            second = largest
            largest = num
        elif num > second and num != largest:
            second = num

    return second if second != float('-inf') else None

def first_unique_char(s):
    char_count = {}
    for char in s:
        char_count[char] = char_count.get(char, 0) + 1

    for i, char in enumerate(s):
        if char_count[char] == 1:
            return i

    return -1

def reverse_words(sentence):
    words = sentence.split()
    return ' '.join(reversed(words))

def find_peak_element(nums):
    left, right = 0, len(nums) - 1

    while left < right:
        mid = (left + right) // 2
        if nums[mid] < nums[mid + 1]:
            left = mid + 1
        else:
            right = mid

    return left

def is_happy_number(n):
    seen = set()
    while n != 1 and n not in seen:
        seen.add(n)
        n = sum(int(digit) ** 2 for digit in str(n))
    return n == 1

def binary_search_recursive(arr, target, left, right):
    if left > right:
        return -1

    mid = (left + right) // 2

    if arr[mid] == target:
        return mid
    elif arr[mid] > target:
        return binary_search_recursive(arr, target, left, mid - 1)
    else:
        return binary_search_recursive(arr, target, mid + 1, right)

def fibonacci_dp(n):
    if n <= 1:
        return n

    dp = [0] * (n + 1)
    dp[1] = 1

    for i in range(2, n + 1):
        dp[i] = dp[i-1] + dp[i-2]

    return dp[n]

def dutch_national_flag(arr):
    low, mid, high = 0, 0, len(arr) - 1

    while mid <= high:
        if arr[mid] == 0:
            arr[low], arr[mid] = arr[mid], arr[low]
            low += 1
            mid += 1
        elif arr[mid] == 1:
            mid += 1
        else:  # arr[mid] == 2
            arr[mid], arr[high] = arr[high], arr[mid]
            high -= 1

    return arr

def next_permutation(nums):
    i = len(nums) - 2
    while i >= 0 and nums[i] >= nums[i + 1]:
        i -= 1

    if i >= 0:
        j = len(nums) - 1
        while nums[j] <= nums[i]:
            j -= 1
        nums[i], nums[j] = nums[j], nums[i]

    left, right = i + 1, len(nums) - 1
    while left < right:
        nums[left], nums[right] = nums[right], nums[left]
        left += 1
        right -= 1

    return nums

def is_perfect_square(num):
    if num < 0:
        return False

    left, right = 0, num
    while left <= right:
        mid = (left + right) // 2
        square = mid * mid

        if square == num:
            return True
        elif square < num:
            left = mid + 1
        else:
            right = mid - 1

    return False

def has_cycle(head):
    if not head or not head.next:
        return False

    slow = head
    fast = head.next

    while slow != fast:
        if not fast or not fast.next:
            return False
        slow = slow.next
        fast = fast.next.next

    return True

def generate_pascals_triangle(num_rows):
    if num_rows == 0:
        return []

    result = [[1]]

    for i in range(1, num_rows):
        row = [1]
        for j in range(1, i):
            row.append(result[i-1][j-1] + result[i-1][j])
        row.append(1)
        result.append(row)

    return result

def bubble_sort(arr):
    # Standard Bubble Sort
    n = len(arr)
    for i in range(n):
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr

def insertion_sort(arr):
    # Standard Insertion Sort
    for i in range(1, len(arr)):
        key = arr[i]
        j = i - 1
        while j >= 0 and key < arr[j]:
            arr[j+1] = arr[j]
            j -= 1
        arr[j+1] = key
    return arr

def selection_sort(arr):
    # Standard Selection Sort
    n = len(arr)
    for i in range(n):
        min_idx = i
        for j in range(i+1, n):
            if arr[j] < arr[min_idx]:
                min_idx = j
        arr[i], arr[min_idx] = arr[min_idx], arr[i]
    return arr

def has_duplicates(lst):
    # Check for duplicates using two nested loops
    for i in range(len(lst)):
        for j in range(i+1, len(lst)):
            if lst[i] == lst[j]:
                return True
    return False

def all_pairs(lst):
    # Return all possible ordered pairs
    pairs = []
    for i in range(len(lst)):
        for j in range(len(lst)):
            pairs.append((lst[i], lst[j]))
    return pairs

def count_common(a, b):
    # Count common elements between two lists
    count = 0
    for x in a:
        for y in b:
            if x == y:
                count += 1
    return count

def is_sublist_brute(a, b):
    # Brute force check if any element of 'a' is in 'b'
    for i in range(len(a)):
        for j in range(len(b)):
            if a[i] == b[j]:
                return True
    return False

def naive_string_match(txt, pat):
    # Naive substring search
    n, m = len(txt), len(pat)
    for i in range(n - m + 1):
        match = True
        for j in range(m):
            if txt[i+j] != pat[j]:
                match = False
                break
        if match:
            return i
    return -1

def find_pairs_sum_k(lst, k):
    # Find all pairs that sum up to k
    pairs = []
    n = len(lst)
    for i in range(n):
        for j in range(i+1, n):
            if lst[i] + lst[j] == k:
                pairs.append((lst[i], lst[j]))
    return pairs

def remove_duplicates_brute(lst):
    # Remove duplicates using nested loops
    result = []
    for i in lst:
        exists = False
        for j in result:
            if i == j:
                exists = True
                break
        if not exists:
            result.append(i)
    return result

def check_anagrams(a, b):
    # Check anagrams by comparing character counts (inefficiently)
    if len(a) != len(b):
        return False
    for ch in a:
        if a.count(ch) != b.count(ch):
            return False
    return True

def find_majority_naive(arr):
    # Find element that appears more than n/2 times
    n = len(arr)
    for i in range(n):
        count = 0
        for j in range(n):
            if arr[i] == arr[j]:
                count += 1
        if count > n//2:
            return arr[i]
    return None

def find_duplicates(lst):
    # Return list of duplicates found by comparing each pair
    duplicates = []
    n = len(lst)
    for i in range(n):
        for j in range(i+1, n):
            if lst[i] == lst[j] and lst[i] not in duplicates:
                duplicates.append(lst[i])
    return duplicates

def count_inversions(arr):
    # Count inversions in an array (brute-force)
    count = 0
    n = len(arr)
    for i in range(n):
        for j in range(i+1, n):
            if arr[i] > arr[j]:
                count += 1
    return count

def palindrome_pairs(words):
    # Find index pairs where the concatenation yields a palindrome
    res = []
    n = len(words)
    for i in range(n):
        for j in range(n):
            if i != j and (words[i] + words[j] == (words[i] + words[j])[::-1]):
                res.append((i, j))
    return res

def naive_transpose(matrix):
    # Transpose a matrix (assuming rectangular, square = O(n^2))
    rows, cols = len(matrix), len(matrix[0])
    result = [[0]*rows for _ in range(cols)]
    for i in range(rows):
        for j in range(cols):
            result[j][i] = matrix[i][j]
    return result

def naive_histogram(lst):
    # Build histogram by counting for each element
    hist = {}
    n = len(lst)
    for i in range(n):
        count = 0
        for j in range(n):
            if lst[i] == lst[j]:
                count += 1
        hist[lst[i]] = count
    return hist

def naive_intersection(a, b):
    # Compute intersection via nested loops
    result = []
    for x in a:
        for y in b:
            if x == y and x not in result:
                result.append(x)
    return result

def naive_union(a, b):
    # Compute union using nested loop membership checks
    result = list(a)
    for x in b:
        exists = False
        for y in result:
            if x == y:
                exists = True
                break
        if not exists:
            result.append(x)
    return result

def find_unique_pairs(lst):
    # List all unique unordered pairs
    result = []
    n = len(lst)
    for i in range(n):
        for j in range(i+1, n):
            result.append((lst[i], lst[j]))
    return result

def naive_rotation_check(a, b):
    # Check if b is a rotation of a
    if len(a) != len(b):
        return False
    n = len(a)
    for i in range(n):
        if a[i:] + a[:i] == b:
            return True
    return False

def naive_2d_search(matrix, target):
    # Search for a target in a 2D matrix
    for row in matrix:
        for val in row:
            if val == target:
                return True
    return False

def naive_most_frequent(lst):
    # Find most frequent element using nested loops
    max_count = 0
    result = None
    n = len(lst)
    for i in range(n):
        count = 0
        for j in range(n):
            if lst[i] == lst[j]:
                count += 1
        if count > max_count:
            max_count = count
            result = lst[i]
    return result

def naive_distinct_pairs(lst):
    # Collect distinct pairs using set to avoid duplicates
    result = set()
    n = len(lst)
    for i in range(n):
        for j in range(i+1, n):
            result.add((lst[i], lst[j]))
    return list(result)

def naive_reverse_pairs(lst):
    # Return pairs (i, j) where lst[i] > lst[j]
    result = []
    n = len(lst)
    for i in range(n):
        for j in range(i+1, n):
            if lst[i] > lst[j]:
                result.append((lst[i], lst[j]))
    return result

def naive_sort_check(lst):
    # Verify if the list is sorted (comparing every pair)
    n = len(lst)
    for i in range(n):
        for j in range(i+1, n):
            if lst[i] > lst[j]:
                return False
    return True

def naive_is_subset(a, b):
    # Check if every element in a is in b using nested loops
    for x in a:
        found = False
        for y in b:
            if x == y:
                found = True
                break
        if not found:
            return False
    return True

def naive_matrix_equal(A, B):
    # Compare two matrices elementwise
    rows = len(A)
    cols = len(A[0])
    for i in range(rows):
        for j in range(cols):
            if A[i][j] != B[i][j]:
                return False
    return True

def naive_count_pairs_divisible_by_k(lst, k):
    # Count pairs whose sum is divisible by k
    count = 0
    n = len(lst)
    for i in range(n):
        for j in range(i+1, n):
            if (lst[i] + lst[j]) % k == 0:
                count += 1
    return count

def naive_longest_substring_no_repeat(s):
    # Find longest substring without repeating characters by checking each starting index
    max_len = 0
    n = len(s)
    for i in range(n):
        seen = set()
        for j in range(i, n):
            if s[j] in seen:
                break
            seen.add(s[j])
        max_len = max(max_len, len(seen))
    return max_len

def naive_lcs_length(a, b):
    # Longest common subsequence length using dynamic programming (DP table fills in O(n*m))
    n, m = len(a), len(b)
    dp = [[0]*(m+1) for _ in range(n+1)]
    for i in range(1, n+1):
        for j in range(1, m+1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])
    return dp[n][m]

def naive_cartesian_product(a, b):
    # Compute Cartesian product of two lists
    result = []
    for i in a:
        for j in b:
            result.append((i, j))
    return result

def naive_symmetric_matrix(matrix):
    # Check if a square matrix is symmetric
    n = len(matrix)
    for i in range(n):
        for j in range(n):
            if matrix[i][j] != matrix[j][i]:
                return False
    return True

def naive_upper_triangular(matrix):
    # Check if a matrix is upper triangular
    n = len(matrix)
    for i in range(1, n):
        for j in range(i):
            if matrix[i][j] != 0:
                return False
    return True

def naive_lower_triangular(matrix):
    # Check if a matrix is lower triangular
    n = len(matrix)
    for i in range(n):
        for j in range(i+1, n):
            if matrix[i][j] != 0:
                return False
    return True

def naive_identity_matrix(matrix):
    # Verify if a matrix is an identity matrix
    n = len(matrix)
    for i in range(n):
        for j in range(n):
            if i == j and matrix[i][j] != 1:
                return False
            elif i != j and matrix[i][j] != 0:
                return False
    return True

def naive_diagonal_matrix(matrix):
    # Check if non-diagonal elements are zero
    n = len(matrix)
    for i in range(n):
        for j in range(n):
            if i != j and matrix[i][j] != 0:
                return False
    return True

def naive_scalar_matrix(matrix):
    # Check if a matrix is a scalar matrix (all diagonal elements equal and others 0)
    n = len(matrix)
    scalar = matrix[0][0]
    for i in range(n):
        for j in range(n):
            if i == j and matrix[i][j] != scalar:
                return False
            elif i != j and matrix[i][j] != 0:
                return False
    return True

def naive_symmetric_difference(a, b):
    # Compute symmetric difference using nested loops
    result = []
    for item in a:
        found = False
        for other in b:
            if item == other:
                found = True
                break
        if not found:
            result.append(item)
    for item in b:
        found = False
        for other in a:
            if item == other:
                found = True
                break
        if not found:
            result.append(item)
    return result

def naive_matrix_scalar_multiplication(matrix, scalar):
    # Multiply each element of a matrix by a scalar
    result = []
    for row in matrix:
        new_row = []
        for item in row:
            new_row.append(item * scalar)
        result.append(new_row)
    return result

def edit_distance_dp(s1, s2):
    # Dynamic programming solution for edit distance
    n, m = len(s1), len(s2)
    dp = [[0]*(m+1) for _ in range(n+1)]
    for i in range(n+1):
        dp[i][0] = i
    for j in range(m+1):
        dp[0][j] = j
    for i in range(1, n+1):
        for j in range(1, m+1):
            if s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])
    return dp[n][m]

def count_subarrays_with_sum(arr, target):
    # Count subarrays that sum to a target (brute force)
    count = 0
    n = len(arr)
    for i in range(n):
        total = 0
        for j in range(i, n):
            total += arr[j]
            if total == target:
                count += 1
    return count

def find_max_pair_sum(arr):
    # Find the maximum sum of any pair of distinct elements
    max_sum = float('-inf')
    n = len(arr)
    for i in range(n):
        for j in range(i+1, n):
            if arr[i] + arr[j] > max_sum:
                max_sum = arr[i] + arr[j]
    return max_sum

def count_equal_pairs(lst):
    # Count pairs of indices with equal values
    count = 0
    n = len(lst)
    for i in range(n):
        for j in range(i+1, n):
            if lst[i] == lst[j]:
                count += 1
    return count

def count_string_pairs(s):
    # Count pairs of identical characters in a string
    count = 0
    n = len(s)
    for i in range(n):
        for j in range(i+1, n):
            if s[i] == s[j]:
                count += 1
    return count

def quadratic_pairwise_products(arr):
    # Compute the sum of products of every distinct pair
    total = 0
    n = len(arr)
    for i in range(n):
        for j in range(i+1, n):
            total += arr[i] * arr[j]
    return total

def check_magic_square(matrix):
    # Verify if a square matrix is magic (all rows, columns, and diagonals have equal sum)
    n = len(matrix)
    s = sum(matrix[0])
    # Check rows
    for row in matrix:
        if sum(row) != s:
            return False
    # Check columns
    for j in range(n):
        col_sum = 0
        for i in range(n):
            col_sum += matrix[i][j]
        if col_sum != s:
            return False
    # Check diagonals
    diag1 = diag2 = 0
    for i in range(n):
        diag1 += matrix[i][i]
        diag2 += matrix[i][n-i-1]
    if diag1 != s or diag2 != s:
        return False
    return True

def generate_all_subarrays(arr):
    # Generate all subarrays (there are O(n^2) of them)
    subarrays = []
    n = len(arr)
    for i in range(n):
        for j in range(i, n):
            subarrays.append(arr[i:j+1])
    return subarrays

def naive_max_subarray_sum(arr):
    # Brute force maximum subarray sum
    n = len(arr)
    max_sum = float('-inf')
    for i in range(n):
        current = 0
        for j in range(i, n):
            current += arr[j]
            max_sum = max(max_sum, current)
    return max_sum

def brute_force_pair_product_sum(arr):
    # Sum of product of every distinct pair
    total = 0
    n = len(arr)
    for i in range(n):
        for j in range(i+1, n):
            total += arr[i] * arr[j]
    return total

def quadratic_string_concatenation(lst):
    # Concatenate every possible pair of strings from list
    result = []
    n = len(lst)
    for i in range(n):
        for j in range(n):
            result.append(lst[i] + lst[j])
    return result

def count_letter_occurrences(s):
    # For each letter, count its occurrences by scanning the string repeatedly
    counts = {}
    for ch in s:
        cnt = 0
        for c in s:
            if ch == c:
                cnt += 1
        counts[ch] = cnt
    return counts

def naive_unique_concatenations(lst):
    # Form unique concatenations of each ordered pair of strings
    result = []
    n = len(lst)
    for i in range(n):
        for j in range(n):
            concat = lst[i] + lst[j]
            if concat not in result:
                result.append(concat)
    return result

def quadratic_closest_elements(lst):
    # For each element, find the closest (by absolute difference) among the others
    n = len(lst)
    closest = [None]*n
    for i in range(n):
        min_diff = float('inf')
        for j in range(n):
            if i != j:
                diff = abs(lst[i] - lst[j])
                if diff < min_diff:
                    min_diff = diff
                    closest[i] = lst[j]
    return closest

def brute_force_string_similarity(s1, s2):
    # Compute a similarity score by comparing every char of s1 with every char of s2
    score = 0
    for ch1 in s1:
        for ch2 in s2:
            if ch1 == ch2:
                score += 1
    return score

def quadratic_common_elements(a, b):
    # Find common elements by comparing each element of a with each of b
    common = []
    for x in a:
        for y in b:
            if x == y and x not in common:
                common.append(x)
    return common

import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def pairwise_gcd(arr):
    # Compute GCD for every distinct pair
    result = []
    n = len(arr)
    for i in range(n):
        for j in range(i+1, n):
            result.append(gcd(arr[i], arr[j]))
    return result

def count_pattern_occurrences(text, pattern):
    # Count how many times pattern appears in text (brute force)
    count = 0
    n, m = len(text), len(pattern)
    for i in range(n - m + 1):
        match = True
        for j in range(m):
            if text[i+j] != pattern[j]:
                match = False
                break
        if match:
            count += 1
    return count

def count_less_than(lst, threshold):
    # For each element, count how many elements are less than the threshold
    counts = []
    n = len(lst)
    for i in range(n):
        cnt = 0
        for j in range(n):
            if lst[j] < threshold:
                cnt += 1
        counts.append(cnt)
    return counts

def min_diff_between_pairs(lst):
    # Find the minimum absolute difference between any two distinct elements
    n = len(lst)
    min_diff = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            diff = abs(lst[i]-lst[j])
            if diff < min_diff:
                min_diff = diff
    return min_diff

def find_pair_with_diff(arr, diff_target):
    # Find any pair that has an absolute difference equal to diff_target
    n = len(arr)
    for i in range(n):
        for j in range(i+1, n):
            if abs(arr[i]-arr[j]) == diff_target:
                return (arr[i], arr[j])
    return None

def count_anagram_pairs(lst):
    # Given a list of strings, count how many unordered pairs are anagrams
    count = 0
    n = len(lst)
    for i in range(n):
        for j in range(i+1, n):
            if sorted(lst[i]) == sorted(lst[j]):
                count += 1
    return count

def pairwise_sum(arr):
    # Return a list of sums for every distinct pair
    result = []
    n = len(arr)
    for i in range(n):
        for j in range(i+1, n):
            result.append(arr[i] + arr[j])
    return result

def quadratic_string_match(s, sub):
    # Another variant of substring search using nested loops
    n, m = len(s), len(sub)
    for i in range(n-m+1):
        found = True
        for j in range(m):
            if s[i+j] != sub[j]:
                found = False
                break
        if found:
            return i
    return -1

def common_prefix_among_pairs(strings):
    # For every pair of strings, determine their common prefix
    prefixes = []
    n = len(strings)
    for i in range(n):
        for j in range(i+1, n):
            prefix = ''
            s1, s2 = strings[i], strings[j]
            for k in range(min(len(s1), len(s2))):
                if s1[k] == s2[k]:
                    prefix += s1[k]
                else:
                    break
            prefixes.append(prefix)
    return prefixes

def length_differences(lst):
    # Compute absolute differences between lengths of every pair of strings
    diffs = []
    n = len(lst)
    for i in range(n):
        for j in range(i+1, n):
            diffs.append(abs(len(lst[i]) - len(lst[j])))
    return diffs

def product_matrix(lst):
    # Form a matrix where element (i,j) is the product of lst[i] and lst[j]
    n = len(lst)
    result = []
    for i in range(n):
        row = []
        for j in range(n):
            row.append(lst[i] * lst[j])
        result.append(row)
    return result

def difference_matrix(lst):
    # Form a matrix of absolute differences for every pair of numbers in lst
    n = len(lst)
    result = []
    for i in range(n):
        row = []
        for j in range(n):
            row.append(abs(lst[i] - lst[j]))
        result.append(row)
    return result

def remove_substring_quadratic(s, sub):
    # Remove all occurrences of 'sub' from 's' using a nested search
    while sub in s:
        for i in range(len(s)-len(sub)+1):
            if s[i:i+len(sub)] == sub:
                s = s[:i] + s[i+len(sub):]
                break
    return s

def count_vowels_in_substrings(s):
    # For each substring of s, count vowels
    vowels = set('aeiouAEIOU')
    counts = []
    n = len(s)
    for i in range(n):
        for j in range(i, n):
            cnt = 0
            for ch in s[i:j+1]:
                if ch in vowels:
                    cnt += 1
            counts.append(cnt)
    return counts

def brute_force_hashes(s):
    # Compute a simple hash for every substring of s
    hashes = []
    n = len(s)
    for i in range(n):
        for j in range(i, n):
            h = 0
            for ch in s[i:j+1]:
                h = h*31 + ord(ch)
            hashes.append(h)
    return hashes

def count_palindromic_substrings(s):
    # Count substrings that are palindromes by checking each substring
    count = 0
    n = len(s)
    for i in range(n):
        for j in range(i, n):
            substr = s[i:j+1]
            if substr == substr[::-1]:
                count += 1
    return count

def adjacent_sum_matrix(matrix):
    # For each cell in a matrix, compute the sum of its adjacent cells (naively)
    rows, cols = len(matrix), len(matrix[0])
    result = [[0]*cols for _ in range(rows)]
    for i in range(rows):
        for j in range(cols):
            total = 0
            for di in [-1, 0, 1]:
                for dj in [-1, 0, 1]:
                    ni, nj = i+di, j+dj
                    if 0 <= ni < rows and 0 <= nj < cols and not (di==0 and dj==0):
                        total += matrix[ni][nj]
            result[i][j] = total
    return result

def count_grid_neighbors(grid):
    # For each cell in a 2D grid, count neighbors with a value of 1 (naively checking 8 directions)
    rows, cols = len(grid), len(grid[0])
    result = [[0]*cols for _ in range(rows)]
    for i in range(rows):
        for j in range(cols):
            count = 0
            for di in [-1, 0, 1]:
                for dj in [-1, 0, 1]:
                    if di == 0 and dj == 0:
                        continue
                    ni, nj = i+di, j+dj
                    if 0 <= ni < rows and 0 <= nj < cols and grid[ni][nj] == 1:
                        count += 1
            result[i][j] = count
    return result

def border_elements_sum(matrix):
    # Sum border elements of a matrix by scanning its indices twice
    rows, cols = len(matrix), len(matrix[0])
    total = 0
    for i in range(rows):
        for j in range(cols):
            if i==0 or j==0 or i==rows-1 or j==cols-1:
                total += matrix[i][j]
    return total

def frequency_difference(lst):
    # For every pair in lst, compute absolute difference of their frequencies (inefficiently)
    diffs = []
    n = len(lst)
    for i in range(n):
        for j in range(i+1, n):
            diff = abs(lst.count(lst[i]) - lst.count(lst[j]))
            diffs.append(diff)
    return diffs

def string_pairing(s):
    # Pair each character with every other and concatenate
    pairs = []
    n = len(s)
    for i in range(n):
        for j in range(n):
            pairs.append(s[i] + s[j])
    return pairs

def word_pairing(words):
    # Concatenate every pair of words
    pairs = []
    n = len(words)
    for i in range(n):
        for j in range(n):
            pairs.append(words[i] + ' ' + words[j])
    return pairs

def substring_aggregation(s):
    # Concatenate all substrings into a list
    aggr = []
    n = len(s)
    for i in range(n):
        for j in range(i, n):
            aggr.append(s[i:j+1])
    return aggr

def compare_arrays_elementwise(a, b):
    # Compare every pair of elements from two arrays
    count = 0
    for x in a:
        for y in b:
            if x == y:
                count += 1
    return count

def nested_loop_index_pairs(lst):
    # Return all index pairs from a list
    indices = []
    n = len(lst)
    for i in range(n):
        for j in range(n):
            indices.append((i, j))
    return indices

def max_difference(lst):
    # Find maximum difference between any two elements
    max_diff = float('-inf')
    n = len(lst)
    for i in range(n):
        for j in range(i+1, n):
            max_diff = max(max_diff, abs(lst[i]-lst[j]))
    return max_diff

def closest_sum_pair(lst, target):
    # Find the pair whose sum is closest to target
    best = None
    min_diff = float('inf')
    n = len(lst)
    for i in range(n):
        for j in range(i+1, n):
            s = lst[i] + lst[j]
            if abs(s - target) < min_diff:
                min_diff = abs(s - target)
                best = (lst[i], lst[j])
    return best

def bubble_sort_variant(arr):
    # A variant of bubble sort using double loop without early break
    n = len(arr)
    for i in range(n):
        for j in range(n-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr

def insertion_sort_variant(arr):
    # Insertion sort implemented with explicit nested loops
    n = len(arr)
    for i in range(1, n):
        j = i
        while j > 0 and arr[j-1] > arr[j]:
            arr[j-1], arr[j] = arr[j], arr[j-1]
            j -= 1
    return arr

def selection_sort_variant(arr):
    # Selection sort variant with nested loop for min search
    n = len(arr)
    for i in range(n):
        min_idx = i
        for j in range(i+1, n):
            if arr[j] < arr[min_idx]:
                min_idx = j
        if i != min_idx:
            arr[i], arr[min_idx] = arr[min_idx], arr[i]
    return arr

def element_swap_quadratic(arr):
    # Swap every distinct pair of elements and return list of swapped copies
    results = []
    n = len(arr)
    for i in range(n):
        for j in range(i+1, n):
            new_arr = arr.copy()
            new_arr[i], new_arr[j] = new_arr[j], new_arr[i]
            results.append(new_arr)
    return results

def index_difference_max(arr):
    # Compute maximum difference between indices for which arr[i] != arr[j]
    max_diff = 0
    n = len(arr)
    for i in range(n):
        for j in range(i+1, n):
            if arr[i] != arr[j]:
                max_diff = max(max_diff, j - i)
    return max_diff

def binary_search_iterative(lst, target):
    low, high = 0, len(lst)-1
    while low <= high:
        mid = (low + high) // 2
        if lst[mid] == target:
            return mid
        elif lst[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def binary_search_recursive(lst, target, low=0, high=None):
    if high is None:
        high = len(lst)-1
    if low > high:
        return -1
    mid = (low + high) // 2
    if lst[mid] == target:
        return mid
    elif lst[mid] < target:
        return binary_search_recursive(lst, target, mid+1, high)
    else:
        return binary_search_recursive(lst, target, low, mid-1)

def binary_search_leftmost(lst, target):
    low, high, result = 0, len(lst)-1, -1
    while low <= high:
        mid = (low + high) // 2
        if lst[mid] >= target:
            if lst[mid] == target:
                result = mid
            high = mid - 1
        else:
            low = mid + 1
    return result

def binary_search_rightmost(lst, target):
    low, high, result = 0, len(lst)-1, -1
    while low <= high:
        mid = (low + high) // 2
        if lst[mid] <= target:
            if lst[mid] == target:
                result = mid
            low = mid + 1
        else:
            high = mid - 1
    return result

def int_log2_iterative(n):
    count = 0
    while n > 1:
        n //= 2
        count += 1
    return count

def int_log2_recursive(n):
    if n <= 1:
        return 0
    return 1 + int_log2_recursive(n // 2)

def power_iterative(x, n):
    # Exponentiation by squaring (iterative)
    result = 1
    while n > 0:
        if n % 2 == 1:
            result *= x
        x *= x
        n //= 2
    return result

def power_recursive(x, n):
    # Exponentiation by squaring (recursive)
    if n == 0:
        return 1
    elif n % 2 == 0:
        return power_recursive(x*x, n//2)
    else:
        return x * power_recursive(x*x, n//2)

def sqrt_binary_search(x, epsilon=1e-6):
    if x < 0:
        return None
    low, high = 0, max(1, x)
    while high - low > epsilon:
        mid = (low + high) / 2
        if mid*mid < x:
            low = mid
        else:
            high = mid
    return (low + high) / 2

def find_first_ge(lst, target):
    # Returns first index where element is >= target
    low, high, result = 0, len(lst)-1, -1
    while low <= high:
        mid = (low+high)//2
        if lst[mid] >= target:
            result = mid
            high = mid - 1
        else:
            low = mid + 1
    return result

def find_last_le(lst, target):
    # Returns last index where element is <= target
    low, high, result = 0, len(lst)-1, -1
    while low <= high:
        mid = (low+high)//2
        if lst[mid] <= target:
            result = mid
            low = mid + 1
        else:
            high = mid - 1
    return result

def binary_search_tuples(lst, key, target):
    # Searches a list of tuples by key (assumes lst sorted by tuple[key])
    low, high = 0, len(lst)-1
    while low <= high:
        mid = (low+high)//2
        if lst[mid][key] == target:
            return mid
        elif lst[mid][key] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def binary_search_in_range(lst, target, low, high):
    # Binary search within indices low and high (inclusive)
    while low <= high:
        mid = (low+high)//2
        if lst[mid] == target:
            return mid
        elif lst[mid] < target:
            low = mid+1
        else:
            high = mid-1
    return -1

def rotated_array_search(nums, target):
    # Search target in a rotated sorted array
    low, high = 0, len(nums)-1
    while low <= high:
        mid = (low+high)//2
        if nums[mid] == target:
            return mid
        if nums[low] <= nums[mid]:
            if nums[low] <= target < nums[mid]:
                high = mid - 1
            else:
                low = mid + 1
        else:
            if nums[mid] < target <= nums[high]:
                low = mid + 1
            else:
                high = mid - 1
    return -1

def find_peak_element(lst):
    # Finds a peak element in a unimodal list
    low, high = 0, len(lst)-1
    while low < high:
        mid = (low+high)//2
        if lst[mid] < lst[mid+1]:
            low = mid + 1
        else:
            high = mid
    return low

def binary_exponentiation_iterative(x, n):
    # Iterative binary exponentiation variant
    res = 1
    while n:
        if n & 1:
            res *= x
        x *= x
        n >>= 1
    return res

def binary_exponentiation_recursive(x, n):
    # Recursive binary exponentiation variant
    if n == 0:
        return 1
    temp = binary_exponentiation_recursive(x, n//2)
    if n % 2 == 0:
        return temp * temp
    else:
        return x * temp * temp

def bst_search(root, target):
    # Assumes BST nodes with 'value', 'left', 'right'
    current = root
    while current is not None:
        if current.value == target:
            return current
        elif current.value < target:
            current = current.right
        else:
            current = current.left
    return None

def bst_insert_balanced(root, node):
    # Insert a node into a balanced BST (assumes balance maintained externally)
    if root is None:
        return node
    current = root
    while True:
        if node.value < current.value:
            if current.left is None:
                current.left = node
                break
            current = current.left
        else:
            if current.right is None:
                current.right = node
                break
            current = current.right
    return root

def avl_tree_find(root, target):
    # Search in an AVL tree
    if root is None:
        return None
    if root.value == target:
        return root
    elif target < root.value:
        return avl_tree_find(root.left, target)
    else:
        return avl_tree_find(root.right, target)

def find_closest_in_bst(root, target):
    # Finds the value in BST closest to target
    closest = root.value
    current = root
    while current:
        if abs(current.value - target) < abs(closest - target):
            closest = current.value
        if target < current.value:
            current = current.left
        else:
            current = current.right
    return closest

def binary_search_custom_cmp(lst, target, cmp_func):
    # Binary search using a custom comparator cmp_func(a, b)
    low, high = 0, len(lst)-1
    while low <= high:
        mid = (low + high) // 2
        cmp_result = cmp_func(lst[mid], target)
        if cmp_result == 0:
            return mid
        elif cmp_result < 0:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def upper_bound_search(lst, target):
    # Returns the smallest index with element > target
    low, high, ans = 0, len(lst), len(lst)
    while low < high:
        mid = (low + high) // 2
        if lst[mid] > target:
            ans = mid
            high = mid
        else:
            low = mid + 1
    return ans

def lower_bound_search(lst, target):
    # Returns the smallest index with element >= target
    low, high, ans = 0, len(lst), len(lst)
    while low < high:
        mid = (low + high) // 2
        if lst[mid] >= target:
            ans = mid
            high = mid
        else:
            low = mid + 1
    return ans

def descending_binary_search(lst, target):
    # Binary search on a descendingly sorted list
    low, high = 0, len(lst)-1
    while low <= high:
        mid = (low + high) // 2
        if lst[mid] == target:
            return mid
        elif lst[mid] > target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def approximate_log2_recursive(n):
    # Recursively compute approximate floor(log2(n))
    return 0 if n < 2 else 1 + approximate_log2_recursive(n//2)

def find_floor_sqrt(x):
    # Find floor of sqrt(x) using binary search
    if x < 0:
        return None
    low, high = 0, x
    while low <= high:
        mid = (low+high)//2
        if mid*mid <= x < (mid+1)*(mid+1):
            return mid
        elif mid*mid > x:
            high = mid-1
        else:
            low = mid+1
    return low

def find_ceil_sqrt(x):
    # Find ceiling of sqrt(x) using binary search
    if x < 0:
        return None
    low, high = 0, x
    while low <= high:
        mid = (low+high)//2
        if mid*mid < x <= (mid+1)*(mid+1):
            return mid+1
        elif mid*mid < x:
            low = mid+1
        else:
            high = mid-1
    return low

def binary_search_strings(lst, target):
    # Binary search in a sorted list of strings
    low, high = 0, len(lst)-1
    while low <= high:
        mid = (low+high)//2
        if lst[mid] == target:
            return mid
        elif lst[mid] < target:
            low = mid+1
        else:
            high = mid-1
    return -1

def binary_search_with_predicate(lst, predicate):
    # Find first index where predicate(element) is True using binary search
    low, high, ans = 0, len(lst)-1, -1
    while low <= high:
        mid = (low+high)//2
        if predicate(lst[mid]):
            ans = mid
            high = mid-1
        else:
            low = mid+1
    return ans

def interval_binary_search(intervals, value):
    # Find interval (tuple) in sorted list whose start <= value <= end
    low, high = 0, len(intervals)-1
    while low <= high:
        mid = (low+high)//2
        start, end = intervals[mid]
        if start <= value <= end:
            return intervals[mid]
        elif value < start:
            high = mid-1
        else:
            low = mid+1
    return None

def binary_search_sorted_keys(d, target):
    # Given a dict with sorted keys, perform binary search over its keys
    keys = sorted(d.keys())
    low, high = 0, len(keys)-1
    while low <= high:
        mid = (low+high)//2
        if keys[mid] == target:
            return d[keys[mid]]
        elif keys[mid] < target:
            low = mid+1
        else:
            high = mid-1
    return None

def binary_search_bounds(lst, target):
    # Return (lower_bound, upper_bound) indices for target
    return (lower_bound_search(lst, target), upper_bound_search(lst, target))

def binary_search_recursive_variant(lst, target, lo=0, hi=None):
    if hi is None:
        hi = len(lst)-1
    if lo > hi:
        return -1
    mid = (lo+hi)//2
    if lst[mid] == target:
        return mid
    elif lst[mid] < target:
        return binary_search_recursive_variant(lst, target, mid+1, hi)
    else:
        return binary_search_recursive_variant(lst, target, lo, mid-1)

def binary_search_variant1(arr, x):
    lo, hi = 0, len(arr)-1
    while lo < hi:
        mid = lo + (hi-lo)//2
        if arr[mid] < x:
            lo = mid+1
        else:
            hi = mid
    return lo if arr[lo] == x else -1

def binary_search_variant2(arr, x):
    lo, hi = 0, len(arr)
    while lo < hi:
        mid = (lo+hi)//2
        if arr[mid] <= x:
            lo = mid+1
        else:
            hi = mid
    return lo-1

def binary_search_variant3(sorted_list, target):
    low, high = 0, len(sorted_list)-1
    while low <= high:
        mid = (low + high) >> 1
        if sorted_list[mid] == target:
            return mid
        elif sorted_list[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def binary_search_variant4(a, key):
    l, r = 0, len(a)-1
    while l <= r:
        m = (l+r)//2
        if a[m] == key:
            return m
        elif a[m] < key:
            l = m+1
        else:
            r = m-1
    return -1

def binary_search_variant5(lst, t):
    i, j = 0, len(lst) - 1
    while i <= j:
        mid = (i + j) // 2
        if lst[mid] == t:
            return mid
        elif lst[mid] > t:
            j = mid - 1
        else:
            i = mid + 1
    return -1

def binary_search_variant6(items, target):
    start, end = 0, len(items) - 1
    while start <= end:
        mid = (start + end) // 2
        if items[mid] == target:
            return mid
        elif items[mid] < target:
            start = mid + 1
        else:
            end = mid - 1
    return -1

def binary_search_variant7(data, val):
    lo, hi = 0, len(data)-1
    while lo <= hi:
        mid = (lo+hi)//2
        if data[mid] < val:
            lo = mid+1
        elif data[mid] > val:
            hi = mid-1
        else:
            return mid
    return -1

def binary_search_variant8(seq, target):
    low, high = 0, len(seq)-1
    while low <= high:
        mid = (low+high) // 2
        if seq[mid] == target:
            return mid
        elif seq[mid] < target:
            low = mid+1
        else:
            high = mid-1
    return -1

def binary_search_variant9(seq, t):
    left, right = 0, len(seq)-1
    while left <= right:
        mid = (left+right)//2
        if seq[mid] == t:
            return mid
        elif seq[mid] < t:
            left = mid+1
        else:
            right = mid-1
    return -1

def binary_search_variant10(a, target):
    low = 0
    high = len(a)-1
    while low <= high:
        mid = (low+high)//2
        if a[mid] == target:
            return mid
        elif a[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def log_search_example2(n):
    # Recursive division to count steps
    if n < 2:
        return 0
    return 1 + log_search_example2(n//2)

def binary_partition_search(arr, target):
    # Partition search: find the position where target would be inserted
    low, high = 0, len(arr)
    while low < high:
        mid = (low+high)//2
        if arr[mid] < target:
            low = mid+1
        else:
            high = mid
    return low

def binary_search_on_ids(ids, target_id):
    # Binary search over sorted list of IDs
    low, high = 0, len(ids)-1
    while low <= high:
        mid = (low+high)//2
        if ids[mid] == target_id:
            return mid
        elif ids[mid] < target_id:
            low = mid+1
        else:
            high = mid-1
    return -1

def binary_search_on_timestamps(timestamps, target):
    # Given sorted timestamps, find target timestamp
    low, high = 0, len(timestamps)-1
    while low <= high:
        mid = (low+high)//2
        if timestamps[mid] == target:
            return mid
        elif timestamps[mid] < target:
            low = mid+1
        else:
            high = mid-1
    return -1

def binary_search_on_scores(scores, target):
    # Binary search on sorted list of scores
    low, high = 0, len(scores)-1
    while low <= high:
        mid = (low+high)//2
        if scores[mid] == target:
            return mid
        elif scores[mid] < target:
            low = mid+1
        else:
            high = mid-1
    return -1

def binary_search_custom_order(lst, target):
    # Binary search on a list sorted in custom order
    low, high = 0, len(lst)-1
    while low <= high:
        mid = (low+high)//2
        if lst[mid] == target:
            return mid
        # Assume custom order is implemented in a comparator
        if custom_compare(lst[mid], target) < 0:
            low = mid+1
        else:
            high = mid-1
    return -1

def custom_compare(a, b):
    return (a > b) - (a < b)

def binary_search_integer_range(n, target):
    # Search for target in range 0 to n (simulate sorted range)
    low, high = 0, n-1
    while low <= high:
        mid = (low+high)//2
        if mid == target:
            return mid
        elif mid < target:
            low = mid+1
        else:
            high = mid-1
    return -1

def binary_search_divide_and_conquer(lst, target):
    # Standard divide and conquer binary search
    low, high = 0, len(lst)-1
    while low <= high:
        mid = (low+high)//2
        if lst[mid] == target:
            return mid
        elif lst[mid] < target:
            low = mid+1
        else:
            high = mid-1
    return -1

def recursive_log_reduction(n):
    # Recursively reduce n by half
    if n == 0:
        return 0
    return 1 + recursive_log_reduction(n//2)

def find_nearest_power_of_two(n):
    # Find the smallest power of 2 greater than or equal to n
    power = 1
    while power < n:
        power *= 2
    return power

def binary_search_position(arr, target):
    # Returns the insertion position of target in sorted arr
    lo, hi = 0, len(arr)
    while lo < hi:
        mid = (lo+hi)//2
        if arr[mid] < target:
            lo = mid+1
        else:
            hi = mid
    return lo

def binary_search_index_finder(arr, target):
    # Find index of target using binary search
    low, high = 0, len(arr)-1
    while low <= high:
        mid = (low+high)//2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid+1
        else:
            high = mid-1
    return -1

def sorted_array_binary_search(arr, target):
    # Simple binary search for sorted array
    low, high = 0, len(arr)-1
    while low <= high:
        mid = (low+high)//2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid+1
        else:
            high = mid-1
    return -1

def bisect_left_manual(a, x):
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo+hi)//2
        if a[mid] < x:
            lo = mid+1
        else:
            hi = mid
    return lo

def bisect_right_manual(a, x):
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo+hi)//2
        if x < a[mid]:
            hi = mid
        else:
            lo = mid+1
    return lo

def binary_search_minimum(arr):
    # Find minimum element in a unimodal array
    low, high = 0, len(arr)-1
    while low < high:
        mid = (low+high)//2
        if arr[mid] > arr[high]:
            low = mid+1
        else:
            high = mid
    return arr[low]

def binary_search_maximum(arr):
    # Find maximum element in a unimodal array
    low, high = 0, len(arr)-1
    while low < high:
        mid = (low+high+1)//2
        if arr[mid] < arr[low]:
            high = mid-1
        else:
            low = mid
    return arr[low]

def binary_search_optimal(arr, target):
    # An optimal binary search returning index or -1
    lo, hi = 0, len(arr)-1
    while lo <= hi:
        mid = (lo+hi)//2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            lo = mid+1
        else:
            hi = mid-1
    return -1

def binary_search_threshold(arr, threshold):
    # Return first index where element >= threshold
    lo, hi = 0, len(arr)-1
    ans = -1
    while lo <= hi:
        mid = (lo+hi)//2
        if arr[mid] >= threshold:
            ans = mid
            hi = mid-1
        else:
            lo = mid+1
    return ans

def binary_search_median_index(arr):
    # For a sorted array, median index can be found in O(1), but we simulate binary search
    return (binary_search_iterative(arr, arr[len(arr)//2]))

def binary_search_ratio(arr, target):
    # Search for target under a custom condition based on ratio
    lo, hi = 0, len(arr)-1
    while lo <= hi:
        mid = (lo+hi)//2
        if abs(arr[mid]-target) < 0.001:
            return mid
        elif arr[mid] < target:
            lo = mid+1
        else:
            hi = mid-1
    return -1

def binary_exponentiation_modulo_iterative(x, n, mod):
    result = 1
    while n > 0:
        if n & 1:
            result = (result * x) % mod
        x = (x * x) % mod
        n //= 2
    return result

def binary_exponentiation_modulo_recursive(x, n, mod):
    if n == 0:
        return 1
    temp = binary_exponentiation_modulo_recursive(x, n//2, mod)
    if n % 2 == 0:
        return (temp * temp) % mod
    else:
        return (x * temp * temp) % mod

def binary_search_loop_counter(lst, target):
    # Returns index and count of iterations
    count = 0
    low, high = 0, len(lst)-1
    while low <= high:
        count += 1
        mid = (low+high)//2
        if lst[mid] == target:
            return mid, count
        elif lst[mid] < target:
            low = mid+1
        else:
            high = mid-1
    return -1, count

def logarithmic_search_on_list(lst, target):
    # A simple binary search wrapper
    return binary_search_iterative(lst, target)

def recursive_divide_solution(n):
    # Divide n by 2 recursively until condition met
    if n <= 1:
        return 1
    return recursive_divide_solution(n//2) + 1

def recursive_find_log(n):
    # Returns number of divisions by 2 until n==0
    if n < 2:
        return 0
    return 1 + recursive_find_log(n//2)

def binary_search_in_increasing_sequence(seq, target):
    # Assumes seq is strictly increasing
    low, high = 0, len(seq)-1
    while low <= high:
        mid = (low+high)//2
        if seq[mid] == target:
            return mid
        elif seq[mid] < target:
            low = mid+1
        else:
            high = mid-1
    return -1

def binary_search_numeric(arr, target):
    low, high = 0, len(arr)-1
    while low <= high:
        mid = (low+high)//2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid+1
        else:
            high = mid-1
    return -1

def binary_search_in_bounds_function(lst, target):
    # Similar to basic binary search but with explicit bounds passed
    return binary_search_in_range(lst, target, 0, len(lst)-1)

def binary_search_fib_like(lst, target):
    # First double an index then binary search in that interval
    index = 1
    while index < len(lst) and lst[index] < target:
        index *= 2
    low = index//2
    high = min(index, len(lst)-1)
    while low <= high:
        mid = (low+high)//2
        if lst[mid] == target:
            return mid
        elif lst[mid] < target:
            low = mid+1
        else:
            high = mid-1
    return -1

def binary_search_doubling(arr, target):
    # Doubling approach then binary search
    i = 1
    while i < len(arr) and arr[i] < target:
        i *= 2
    return binary_search_in_range(arr, target, i//2, min(i, len(arr)-1))

def binary_search_adjusted(arr, target):
    low, high = 0, len(arr)-1
    while low <= high:
        mid = low + (high-low)//2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def binary_search_custom_condition(arr, condition):
    # Binary search for an element that satisfies a custom condition
    low, high = 0, len(arr)-1
    while low <= high:
        mid = (low+high)//2
        if condition(arr[mid]):
            return mid
        elif not condition(arr[mid]):
            low = mid+1
    return -1

def binary_search_with_offset(arr, target, offset):
    # Binary search that applies an offset to mid comparisons
    low, high = 0, len(arr)-1
    while low <= high:
        mid = (low+high)//2 + offset
        if mid >= len(arr):
            high = mid - offset - 1
            continue
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid - offset + 1
        else:
            high = mid - offset - 1
    return -1

def binary_search_for_interval(intervals, value):
    # Find interval where value falls using binary search
    low, high = 0, len(intervals)-1
    while low <= high:
        mid = (low+high)//2
        if intervals[mid][0] <= value <= intervals[mid][1]:
            return intervals[mid]
        elif value < intervals[mid][0]:
            high = mid-1
        else:
            low = mid+1
    return None

def binary_search_minimizer(f, low, high, tol=1e-6):
    # Binary search to find x in [low, high] where f(x) is minimized (assumes unimodal)
    while high - low > tol:
        m1 = low + (high-low)/3
        m2 = high - (high-low)/3
        if f(m1) < f(m2):
            high = m2
        else:
            low = m1
    return (low+high)/2

def binary_search_maximizer(f, low, high, tol=1e-6):
    # Binary search to find x in [low, high] where f(x) is maximized (assumes unimodal)
    while high - low > tol:
        m1 = low + (high-low)/3
        m2 = high - (high-low)/3
        if f(m1) > f(m2):
            high = m2
        else:
            low = m1
    return (low+high)/2

def binary_search_in_rotated(arr, target):
    # Another variant for rotated sorted array
    low, high = 0, len(arr)-1
    while low <= high:
        mid = (low+high)//2
        if arr[mid] == target:
            return mid
        if arr[low] <= arr[mid]:
            if arr[low] <= target < arr[mid]:
                high = mid-1
            else:
                low = mid+1
        else:
            if arr[mid] < target <= arr[high]:
                low = mid+1
            else:
                high = mid-1
    return -1

def binary_search_circular(arr, target):
    # Binary search adapted for circularly sorted array
    low, high = 0, len(arr)-1
    while low <= high:
        mid = (low+high)//2
        if arr[mid] == target:
            return mid
        if arr[low] <= arr[mid]:
            if arr[low] <= target < arr[mid]:
                high = mid-1
            else:
                low = mid+1
        else:
            if arr[mid] < target <= arr[high]:
                low = mid+1
            else:
                high = mid-1
    return -1

def binary_search_balanced(root, target):
    # Search in a balanced BST (assumes node has attributes val, left, right)
    current = root
    while current:
        if current.val == target:
            return current
        elif target < current.val:
            current = current.left
        else:
            current = current.right
    return None

def binary_search_index_leftmost(a, x):
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo+hi)//2
        if a[mid] < x:
            lo = mid+1
        else:
            hi = mid
    return lo

def binary_search_index_rightmost(a, x):
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo+hi)//2
        if a[mid] <= x:
            lo = mid+1
        else:
            hi = mid
    return lo-1

