def binary_search_with_counter(arr, target):
    # Binary search that returns (index, steps)
    steps = 0
    low, high = 0, len(arr)-1
    while low <= high:
        steps += 1
        mid = (low+high)//2
        if arr[mid] == target:
            return mid, steps
        elif arr[mid] < target:
            low = mid+1
        else:
            high = mid-1
    return -1, steps

def binary_search_data(struct, target):
    # Binary search in a list contained within a data structure
    data = struct['data']
    low, high = 0, len(data)-1
    while low <= high:
        mid = (low+high)//2
        if data[mid] == target:
            return mid
        elif data[mid] < target:
            low = mid+1
        else:
