    return -1

def binary_search_extended(arr, target, eps=1e-9):
    # Extended binary search that allows approximate equality
    low, high = 0, len(arr)-1
    while low <= high:
        mid = (low+high)//2
        if abs(arr[mid]-target) < eps:
            return mid
        elif arr[mid] < target:
            low = mid+1
        else:
            high = mid-1
    return -1

