def inversion_count_merge_sort1(arr):
    def merge_count(left, right):
        i = j = count = 0
        merged = []
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                merged.append(left[i]); i += 1
            else:
                merged.append(right[j]); j += 1
                count += len(left) - i
        return merged + left[i:] + right[j:], count
    if len(arr) <= 1:
        return arr, 0
    mid = len(arr)//2
    left, x = inversion_count_merge_sort1(arr[:mid])
    right, y = inversion_count_merge_sort1(arr[mid:])
    merged, z = merge_count(left, right)
    return merged, x + y + z

