def fib_naive(n):
    # NaÃ¯ve recursive Fibonacci (exponential time)
    if n <= 1:
        return n
    return fib_naive(n-1) + fib_naive(n-2)

def power_set_variant1(lst):
    # Generate all subsets (power set) recursively
    if not lst:
        return [ [] ]
    subsets = power_set_variant1(lst[1:])
    return subsets + [[lst[0]] + s for s in subsets]

def binary_strings(n):
    # Generate all binary strings of length n recursively
    if n == 0:
        return ['']
    smaller = binary_strings(n-1)
    return [s+'0' for s in smaller] + [s+'1' for s in smaller]

