def nested_loop_variant1(m, n):
    # Sums the chosen indices
    total = 0
    def rec(depth, current):
        nonlocal total
        if depth == m:
            total += sum(current)
        else:
            for i in range(n):
                rec(depth+1, current + [i])
    rec(0, [])
    return total

def nested_loop_variant2(m, n):
    # Counts the total number of complete mâlevel sequences
    total = 0
    def rec(depth):
        nonlocal total
        if depth == m:
            total += 1
        else:
            for i in range(n):
                rec(depth+1)
    rec(0)
    return total

def nested_loop_variant3(m, n):
    # Sums the product (over each complete sequence) of the chosen indices
    def prod(lst):
        p = 1
        for x in lst:
            p *= x
        return p
    total = 0
    def rec(depth, current):
        nonlocal total
        if depth == m:
            total += prod(current)
        else:
            for i in range(n):
                rec(depth+1, current + [i])
    rec(0, [])
    return total

